import Cocoa

/// Brand marks for the links on the shortcuts sheet (Simple Icons, CC0), embedded so the binary needs no resource bundle.
enum Logos {
    static let github: NSImage = { let i = NSImage(data: Data(base64Encoded: "")!)!; i.isTemplate = true; return i }()
    static let x: NSImage = { let i = NSImage(data: Data(base64Encoded: "")!)!; i.isTemplate = true; return i }()
}
